// The 2-shard fixture under testdata/multi (repo root, two levels up from
// this package) is generated by testdata/gen's multi mode:
//
//	go run ./testdata/gen multi testdata/multi
//
// Layout (dataStart = 8 + padded header length, per shard):
//
//	shard 1 (model.safetensors-00001-of-00002.safetensors), dataStart 192:
//	  model.layers.0.mlp.up_proj.weight    BF16 [2,4]  in-shard [0,16)
//	  model.layers.0.self_attn.q_proj.weight F16 [2,2] in-shard [16,24)
//	shard 2 (model.safetensors-00002-of-00002.safetensors), dataStart 184:
//	  model.layers.0.input_layernorm.weight F16 [4]    in-shard [0,8)
//	  model.layers.0.mlp.position_ids       I32 [4]    in-shard [8,16)
const (
	multiShard1 = "model.safetensors-00001-of-00002.safetensors"
	multiShard2 = "model.safetensors-00002-of-00002.safetensors"

	fixtureDir      = "../../testdata/multi"
	shard1DataStart = 192
	shard2DataStart = 184

	nameUpProj = "model.layers.0.mlp.up_proj.weight"
	nameQProj  = "model.layers.0.self_attn.q_proj.weight"
	nameNorm   = "model.layers.0.input_layernorm.weight"
	namePosIDs = "model.layers.0.mlp.position_ids"
)

// multiShardPaths returns the committed fixture paths in shard order.
func multiShardPaths() []string {
	return []string{
		filepath.Join(fixtureDir, multiShard1),
		filepath.Join(fixtureDir, multiShard2),
	}
}

// The 2-shard fixture under testdata/multirot is generated by
// testdata/gen's multirot mode: one 256-element tensor per shard (both
// multiples of the ConvRot group size of 256), so every tensor converts
// instead of skipping:
//
//	shard 1: rot.a BF16 [128,2] (128 rows; rotation groups straddle rows)
//	shard 2: rot.b F16  [2,128] (2 rows)
const (
	rotFixtureDir = "../../testdata/multirot"
	rotA          = "rot.a"
	rotB          = "rot.b"
)

// rotShardPaths returns the committed multirot fixture paths in shard
// order (the shard filenames match the multi fixture's).
func rotShardPaths() []string {
	return []string{
		filepath.Join(rotFixtureDir, multiShard1),
		filepath.Join(rotFixtureDir, multiShard2),
	}
}

// outEntry is one expected output header entry.
type outEntry struct {
	name  string
	dtype DType
	off   [2]int64
}

func checkOutHeader(t *testing.T, h *Header, want []outEntry) {
	t.Helper()
	if len(h.Tensors) != len(want) {
		t.Fatalf("output header has %d tensors, want %d", len(h.Tensors), len(want))
	}
	for i, w := range want {
		e := h.Tensors[i]
		if e.Name != w.name || e.Info.DType != w.dtype || e.Info.DataOffsets != w.off {
			t.Errorf("output header[%d] = %s %s %v, want %s %s %v",
				i, e.Name, e.Info.DType, e.Info.DataOffsets, w.name, w.dtype, w.off)
		}
	}
}

func TestPlanModelTwoShards(t *testing.T) {
	plans, outHeader, err := planModel(ConvertOptions{
		InputShards: multiShardPaths(),
		Default:     TargetNone,
	})
	if err != nil {
		t.Fatalf("planModel: %v", err)
	}

	// Global tensor order: shard order, then in-shard header order.
	// Source offsets stay relative to each tensor's own shard file.
	want := []struct {
		name  string
		shard int
		off   int64
		len   int64
	}{
		{nameUpProj, 0, shard1DataStart + 0, 16},
		{nameQProj, 0, shard1DataStart + 16, 8},
		{nameNorm, 1, shard2DataStart + 0, 8},
		{namePosIDs, 1, shard2DataStart + 8, 16},
	}
	if len(plans) != len(want) {
		t.Fatalf("got %d plans, want %d", len(plans), len(want))
	}
	for i, w := range want {
		p := plans[i]
		if p.name != w.name {
			t.Errorf("plan[%d].name = %q, want %q", i, p.name, w.name)
		}
		if p.srcShard != w.shard {
			t.Errorf("plan[%d] (%s).srcShard = %d, want %d", i, w.name, p.srcShard, w.shard)
		}
		if p.srcAbsOffset != w.off {
			t.Errorf("plan[%d] (%s).srcAbsOffset = %d, want %d", i, w.name, p.srcAbsOffset, w.off)
		}
		if p.srcLen != w.len {
			t.Errorf("plan[%d] (%s).srcLen = %d, want %d", i, w.name, p.srcLen, w.len)
		}
		if p.skippedWhy == "" {
			t.Errorf("plan[%d] (%s): TargetNone should passthrough, got a conversion", i, w.name)
		}
	}

	// Output offsets accumulate globally across shards, in the same order.
	checkOutHeader(t, outHeader, []outEntry{
		{nameUpProj, DTypeBF16, [2]int64{0, 16}},
		{nameQProj, DTypeF16, [2]int64{16, 24}},
		{nameNorm, DTypeF16, [2]int64{24, 32}},
		{namePosIDs, DTypeI32, [2]int64{32, 48}},
	})
}

func TestPlanModelTargetsAcrossShards(t *testing.T) {
	plans, outHeader, err := planModel(ConvertOptions{
		InputShards: multiShardPaths(),
		Default:     TargetFP8E4M3,
		MinElems:    5,
	})
	if err != nil {
		t.Fatalf("planModel: %v", err)
	}

	want := []struct {
		name  string
		dtype DType
		skip  bool
	}{
		{nameUpProj, DTypeF8E4M3, false}, // 8 elems >= 5 -> converted
		{nameQProj, DTypeF16, true},      // 4 elems < 5  -> kept
		{nameNorm, DTypeF16, true},       // 4 elems < 5  -> kept (shard 2)
		{namePosIDs, DTypeI32, true},     // non-float    -> kept
	}
	if len(plans) != len(want) {
		t.Fatalf("got %d plans, want %d", len(plans), len(want))
	}
	for i, w := range want {
		p := plans[i]
		if p.name != w.name {
			t.Fatalf("plan[%d].name = %q, want %q", i, p.name, w.name)
		}
		if p.outDType != w.dtype {
			t.Errorf("plan[%d] (%s).outDType = %s, want %s", i, w.name, p.outDType, w.dtype)
		}
		if (p.skippedWhy != "") != w.skip {
			t.Errorf("plan[%d] (%s).skippedWhy = %q, want skipped=%v", i, w.name, p.skippedWhy, w.skip)
		}
	}

	// The converted tensor shrinks to 1 byte/elem, passthrough keeps its
	// size, and offsets keep accumulating across the shard boundary.
	checkOutHeader(t, outHeader, []outEntry{
		{nameUpProj, DTypeF8E4M3, [2]int64{0, 8}},
		{nameQProj, DTypeF16, [2]int64{8, 16}},
		{nameNorm, DTypeF16, [2]int64{16, 24}},
		{namePosIDs, DTypeI32, [2]int64{24, 40}},
	})
}

// singleFixturePath is the committed 1-file gen fixture (testdata/gen's
// single mode): up_proj (BF16 [2,4], 8 elems), q_proj (F16 [2,2]), norm
// (F16 [4]).
const singleFixturePath = "../../testdata/single/single.safetensors"

// TestConvertSingleFP8DefaultProtection runs the single fixture through
// ConvertFile with the default fp8 target and protection enabled (no
// config): the norm weight is kept at its original dtype with the
// protection reason in the report, the attention projection is kept (the
// fp8 rule), and the plain MLP projection still converts to fp8.
func TestConvertSingleFP8DefaultProtection(t *testing.T) {
	out := filepath.Join(t.TempDir(), "out.safetensors")
	stats, err := ConvertFile(ConvertOptions{
		InputPath:  singleFixturePath,
		OutputPath: out,
		Default:    TargetFP8E4M3,
		Protect:    true,
	})
	if err != nil {
		t.Fatalf("ConvertFile: %v", err)
	}
	if len(stats) != 3 {
		t.Fatalf("got %d stats, want 3", len(stats))
	}

	want := []struct {
		name       string
		toDType    DType
		skippedWhy string
	}{
		{nameUpProj, DTypeF8E4M3, ""},
		{nameQProj, DTypeF16, protectReasonAttnProj},
		{nameNorm, DTypeF16, protectReasonNorms},
	}
	for i, w := range want {
		s := stats[i]
		if s.Name != w.name {
			t.Fatalf("stat[%d].Name = %q, want %q", i, s.Name, w.name)
		}
		if s.ToDType != w.toDType {
			t.Errorf("stat (%s).ToDType = %s, want %s", s.Name, s.ToDType, w.toDType)
		}
		if s.SkippedWhy != w.skippedWhy {
			t.Errorf("stat (%s).SkippedWhy = %q, want %q", s.Name, s.SkippedWhy, w.skippedWhy)
		}
	}

	// The protected tensors are passthrough: output dtype equals input
	// dtype (without protection the norm would be F8_E4M3).
	for _, s := range stats[1:] {
		if s.ToDType != s.FromDType {
			t.Errorf("stat (%s): protected tensor converted %s -> %s, want passthrough", s.Name, s.FromDType, s.ToDType)
		}
	}
}

// TestPlanTensorProtectionOrdering pins that protection is decided before
// the mechanical passthrough checks: with MinElems high enough to skip
// every tensor in the single fixture, the protected tensors still report
// their policy reason while the unprotected one reports the mechanical
// one. A config default (not a rule) is a bulk default, so protection
// applies to it too. Zero-value options (Protect unset) keep the
// pre-policy blanket-conversion behavior.
func TestPlanTensorProtectionOrdering(t *testing.T) {
	t.Run("policy reason wins over min-elems", func(t *testing.T) {
		plans, _, err := planModel(ConvertOptions{
			InputShards: []string{singleFixturePath},
			Default:     TargetFP8E4M3,
			Protect:     true,
			MinElems:    100, // all three fixture tensors are smaller
		})
		if err != nil {
			t.Fatalf("planModel: %v", err)
		}
		wantSkip := map[string]string{
			nameUpProj: "fewer than 100 elements", // not protected
			nameQProj:  protectReasonAttnProj,     // fp8 rule
			nameNorm:   protectReasonNorms,        // hard rule
		}
		for _, p := range plans {
			if p.skippedWhy != wantSkip[p.name] {
				t.Errorf("plan (%s).skippedWhy = %q, want %q", p.name, p.skippedWhy, wantSkip[p.name])
			}
		}
	})

	t.Run("config default is not explicit, protection applies", func(t *testing.T) {
		plans, _, err := planModel(ConvertOptions{
			InputShards: []string{singleFixturePath},
			Config:      &Config{Default: "fp8_e4m3"},
			Protect:     true,
		})
		if err != nil {
			t.Fatalf("planModel: %v", err)
		}
		for _, p := range plans {
			if p.name == nameNorm && p.skippedWhy != protectReasonNorms {
				t.Errorf("plan (%s).skippedWhy = %q, want the protection reason (config default is not explicit intent)", p.name, p.skippedWhy)
			}
			if p.name == nameUpProj && p.skippedWhy != "" {
				t.Errorf("plan (%s).skippedWhy = %q, want converted", p.name, p.skippedWhy)
			}
		}
	})

	t.Run("zero-value options keep the old behavior", func(t *testing.T) {
		plans, _, err := planModel(ConvertOptions{
			InputShards: []string{singleFixturePath},
			Default:     TargetFP8E4M3,
		})
		if err != nil {
			t.Fatalf("planModel (no protect): %v", err)
		}
		for _, p := range plans {
			if p.skippedWhy != "" {
				t.Errorf("plan (%s).skippedWhy = %q, want converted (protection off)", p.name, p.skippedWhy)
			}
		}
	})
}

// TestConvertSingleAttnProjFP8OnlyProtection pins that the attention
// projection protection is fp8-only: the single fixture's q_proj is kept
// at its original dtype with the scaling rationale for fp8_e4m3 and
// fp8_e5m2, but converts as an ordinary weight (correct output dtype and
// scale siblings) for the scaled targets int8, mxfp4, nvfp4, and int4 -
// protection must not over-reach to formats that carry a scale.
func TestConvertSingleAttnProjFP8OnlyProtection(t *testing.T) {
	cases := []struct {
		name   string
		target TargetKind
		header []outEntry // full expected output header
		qSkip  string     // q_proj's report skip reason; empty => converted
	}{
		{
			"fp8_e4m3", TargetFP8E4M3,
			[]outEntry{
				{nameUpProj, DTypeF8E4M3, [2]int64{0, 8}},
				{nameQProj, DTypeF16, [2]int64{8, 16}}, // protected: passthrough at F16
				{nameNorm, DTypeF16, [2]int64{16, 24}},
			},
			protectReasonAttnProj,
		},
		{
			"fp8_e5m2", TargetFP8E5M2,
			[]outEntry{
				{nameUpProj, DTypeF8E5M2, [2]int64{0, 8}},
				{nameQProj, DTypeF16, [2]int64{8, 16}}, // protected: passthrough at F16
				{nameNorm, DTypeF16, [2]int64{16, 24}},
			},
			protectReasonAttnProj,
		},
		{
			"int8", TargetInt8,
			[]outEntry{
				{nameUpProj, DTypeI8, [2]int64{0, 8}},
				{nameUpProj + ".scale", DTypeF32, [2]int64{8, 12}},
				{nameQProj, DTypeI8, [2]int64{12, 16}}, // converted: scaled target
				{nameQProj + ".scale", DTypeF32, [2]int64{16, 20}},
				{nameNorm, DTypeF16, [2]int64{20, 28}},
			},
			"",
		},
		{
			"mxfp4", TargetMxFP4,
			[]outEntry{
				{nameUpProj + ".block_scale", DTypeU8, [2]int64{0, 1}},
				{nameUpProj, DTypeU8, [2]int64{1, 5}},
				{nameQProj + ".block_scale", DTypeU8, [2]int64{5, 6}}, // converted: scaled target
				{nameQProj, DTypeU8, [2]int64{6, 8}},
				{nameNorm, DTypeF16, [2]int64{8, 16}},
			},
			"",
		},
		{
			"nvfp4", TargetNVFP4,
			[]outEntry{
				{nameUpProj + ".global_scale", DTypeF32, [2]int64{0, 4}},
				{nameUpProj + ".block_scale", DTypeF8E4M3, [2]int64{4, 5}},
				{nameUpProj, DTypeU8, [2]int64{5, 9}},
				{nameQProj + ".global_scale", DTypeF32, [2]int64{9, 13}}, // converted: scaled target
				{nameQProj + ".block_scale", DTypeF8E4M3, [2]int64{13, 14}},
				{nameQProj, DTypeU8, [2]int64{14, 16}},
				{nameNorm, DTypeF16, [2]int64{16, 24}},
			},
			"",
		},
		{
			"int4", TargetInt4,
			[]outEntry{
				{nameUpProj, DTypeU8, [2]int64{0, 4}},
				{nameUpProj + ".scale", DTypeF32, [2]int64{4, 8}},
				{nameQProj, DTypeU8, [2]int64{8, 10}}, // converted: scaled target
				{nameQProj + ".scale", DTypeF32, [2]int64{10, 14}},
				{nameNorm, DTypeF16, [2]int64{14, 22}},
			},
			"",
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			out := filepath.Join(t.TempDir(), "out.safetensors")
			stats, err := ConvertFile(ConvertOptions{
				InputPath:  singleFixturePath,
				OutputPath: out,
				Default:    tc.target,
				Protect:    true,
			})
			if err != nil {
				t.Fatalf("ConvertFile: %v", err)
			}

			f, err := os.Open(out)
			if err != nil {
				t.Fatalf("opening output: %v", err)
			}
			defer f.Close()
			outHeader, dataStart, err := ReadHeader(f)
			if err != nil {
				t.Fatalf("reading output header: %v", err)
			}
			checkOutHeader(t, outHeader, tc.header)

			var q *TensorStat
			for i := range stats {
				if stats[i].Name == nameQProj {
					q = &stats[i]
				}
			}
			if q == nil {
				t.Fatalf("no stat for %s", nameQProj)
			}
			if q.SkippedWhy != tc.qSkip {
				t.Errorf("stat (%s).SkippedWhy = %q, want %q", nameQProj, q.SkippedWhy, tc.qSkip)
			}
			if tc.qSkip != "" && q.ToDType != q.FromDType {
				t.Errorf("stat (%s): protected tensor converted %s -> %s, want passthrough", nameQProj, q.FromDType, q.ToDType)
			}

			if tc.target == TargetInt8 {
				// The converted q_proj carries a real scale: fixture values
				// 2.0, -2.0, 0.5, -0.5 -> maxAbs 2.0 -> scale 2.0/127.
				for _, e := range outHeader.Tensors {
					if e.Name != nameQProj+".scale" {
						continue
					}
					b := make([]byte, 4)
					if _, err := f.ReadAt(b, dataStart+e.Info.DataOffsets[0]); err != nil {
						t.Fatalf("reading q_proj scale: %v", err)
					}
					if got := math.Float32frombits(binary.LittleEndian.Uint32(b)); got != 2.0/127 {
						t.Errorf("q_proj int8 scale = %v, want %v", got, 2.0/127)
					}
				}
			}
		})
	}
}

// TestConvertSingleExplicitRuleOverridesProtection pins that an explicit
// config rule wins over the protection policy and is flagged for the CLI
// warning: a rule forcing int8 on the norm tensor converts it (with its
// .scale sibling) instead of protecting it, and a rule forcing fp8 on
// q_proj likewise overrides the fp8-only rule. A rule that merely keeps
// a protected name at its original dtype overrides nothing and is not
// counted.
func TestConvertSingleExplicitRuleOverridesProtection(t *testing.T) {
	countOverrides := func(stats []TensorStat) int {
		n := 0
		for _, s := range stats {
			if s.ProtectOverride {
				n++
			}
		}
		return n
	}

	t.Run("rule int8 on norm tensor", func(t *testing.T) {
		cfg := &Config{Rules: []ConfigRule{{Match: nameNorm, DType: "int8"}}}
		out := filepath.Join(t.TempDir(), "out.safetensors")
		stats, err := ConvertFile(ConvertOptions{
			InputPath:  singleFixturePath,
			OutputPath: out,
			Config:     cfg,
			Default:    TargetFP8E4M3,
			Protect:    true,
		})
		if err != nil {
			t.Fatalf("ConvertFile: %v", err)
		}

		f, err := os.Open(out)
		if err != nil {
			t.Fatalf("opening output: %v", err)
		}
		defer f.Close()
		outHeader, _, err := ReadHeader(f)
		if err != nil {
			t.Fatalf("reading output header: %v", err)
		}
		// Explicit rule converts the norm (I8 + .scale after the owner);
		// q_proj has no rule, so the fp8 protection still applies to it.
		checkOutHeader(t, outHeader, []outEntry{
			{nameUpProj, DTypeF8E4M3, [2]int64{0, 8}},
			{nameQProj, DTypeF16, [2]int64{8, 16}},
			{nameNorm, DTypeI8, [2]int64{16, 20}},
			{nameNorm + ".scale", DTypeF32, [2]int64{20, 24}},
		})

		want := map[string]struct {
			toDType  DType
			override bool
			skip     string
		}{
			nameUpProj: {DTypeF8E4M3, false, ""},
			nameQProj:  {DTypeF16, false, protectReasonAttnProj},
			nameNorm:   {DTypeI8, true, ""},
		}
		for _, s := range stats {
			w, ok := want[s.Name]
			if !ok {
				t.Fatalf("unexpected stat for %q", s.Name)
			}
			if s.ToDType != w.toDType || s.ProtectOverride != w.override || s.SkippedWhy != w.skip {
				t.Errorf("stat (%s) = (ToDType %s, override %v, skip %q), want (%s, %v, %q)",
					s.Name, s.ToDType, s.ProtectOverride, s.SkippedWhy, w.toDType, w.override, w.skip)
			}
		}
		// The norm is all 1.0 in the fixture -> int8 scale 1.0/127.
		var norm *TensorStat
		for i := range stats {
			if stats[i].Name == nameNorm {
				norm = &stats[i]
			}
		}
		if norm.Scale != 1.0/127 {
			t.Errorf("norm int8 scale = %v, want %v", norm.Scale, 1.0/127)
		}
		if n := countOverrides(stats); n != 1 {
			t.Errorf("override count = %d, want 1 (only the norm)", n)
		}
	})

	t.Run("rule fp8 on q_proj overrides the fp8-only rule", func(t *testing.T) {
		cfg := &Config{Rules: []ConfigRule{{Match: nameQProj, DType: "fp8_e4m3"}}}
		out := filepath.Join(t.TempDir(), "out.safetensors")
		stats, err := ConvertFile(ConvertOptions{
			InputPath:  singleFixturePath,
			OutputPath: out,
			Config:     cfg,
			Default:    TargetFP8E4M3,
			Protect:    true,
		})
		if err != nil {
			t.Fatalf("ConvertFile: %v", err)
		}

		f, err := os.Open(out)
		if err != nil {
			t.Fatalf("opening output: %v", err)
		}
		defer f.Close()
		outHeader, _, err := ReadHeader(f)
		if err != nil {
			t.Fatalf("reading output header: %v", err)
		}
		// q_proj is converted by the explicit rule; the norm has no rule,
		// so the hard protection still applies to it.
		checkOutHeader(t, outHeader, []outEntry{
			{nameUpProj, DTypeF8E4M3, [2]int64{0, 8}},
			{nameQProj, DTypeF8E4M3, [2]int64{8, 12}},
			{nameNorm, DTypeF16, [2]int64{12, 20}},
		})

		for _, s := range stats {
			wantOverride := s.Name == nameQProj
			if s.ProtectOverride != wantOverride {
				t.Errorf("stat (%s).ProtectOverride = %v, want %v", s.Name, s.ProtectOverride, wantOverride)
			}
			if s.Name == nameNorm && s.SkippedWhy != protectReasonNorms {
				t.Errorf("stat (%s).SkippedWhy = %q, want the norm protection reason", s.Name, s.SkippedWhy)
			}
		}
		if n := countOverrides(stats); n != 1 {
			t.Errorf("override count = %d, want 1 (only q_proj)", n)
		}
	})

	t.Run("rule none on a protected name overrides nothing", func(t *testing.T) {
		cfg := &Config{Rules: []ConfigRule{{Match: nameNorm, DType: "none"}}}
		out := filepath.Join(t.TempDir(), "out.safetensors")
		stats, err := ConvertFile(ConvertOptions{
			InputPath:  singleFixturePath,
			OutputPath: out,
			Config:     cfg,
			Default:    TargetFP8E4M3,
			Protect:    true,
		})
		if err != nil {
			t.Fatalf("ConvertFile: %v", err)
		}
		for _, s := range stats {
			if s.ProtectOverride {
				t.Errorf("stat (%s).ProtectOverride = true, want false (nothing was converted against the policy)", s.Name)
			}
			if s.Name == nameNorm && (s.ToDType != DTypeF16 || s.SkippedWhy == "") {
				t.Errorf("stat (%s) = (%s, %q), want F16 passthrough", s.Name, s.ToDType, s.SkippedWhy)
			}
		}
		if n := countOverrides(stats); n != 0 {
			t.Errorf("override count = %d, want 0", n)
		}
	})
}

// TestConvertSingleNoProtectRestoresBlanketConversion pins the
// -no-protect behavior at the library level: with Protect explicitly
// false, even protected tensors (the norm weight, the attention
