// TestConvertModelMultiFileConvRot runs the multirot fixture (two shards,
// one 256-multiple tensor each) through ConvertModel with multi-file
// output: row-scale siblings land before their owners in each shard, the
// per-tensor bytes match the merged output, the index covers owners and
// scales in file order with a summed total_size, and the output dir
// round-trips both through DiscoverShards and a target-none conversion
// that reproduces the merged file byte-for-byte.
func TestConvertModelMultiFileConvRot(t *testing.T) {
	inIdx, err := LoadIndex(filepath.Join(rotFixtureDir, fixtureIndexName))
	if err != nil {
		t.Fatalf("LoadIndex: %v", err)
	}

	outDir := t.TempDir()
	if _, err := ConvertModel(ConvertOptions{
		InputShards: rotShardPaths(),
		InputIndex:  inIdx,
		OutputDir:   outDir,
		Default:     TargetInt8ConvRot,
	}); err != nil {
		t.Fatalf("ConvertModel: %v", err)
	}

	mergedPath := filepath.Join(t.TempDir(), "merged.safetensors")
	if _, err := ConvertModel(ConvertOptions{
		InputShards: rotShardPaths(),
		OutputPath:  mergedPath,
		Default:     TargetInt8ConvRot,
	}); err != nil {
		t.Fatalf("ConvertModel (merged): %v", err)
	}

	t.Run("output dir has exactly the 2 shards + index", func(t *testing.T) {
		entries, err := os.ReadDir(outDir)
		if err != nil {
			t.Fatalf("reading output dir: %v", err)
		}
		got := make([]string, 0, len(entries))
		for _, e := range entries {
			got = append(got, e.Name())
		}
		want := []string{multiShard1, multiShard2, fixtureIndexName}
		if !reflect.DeepEqual(got, want) {
			t.Errorf("output dir = %v, want exactly %v", got, want)
		}
	})

	t.Run("per-shard headers: row-scale siblings before owners", func(t *testing.T) {
		// Shard 1: rot.a [128,2] -> 128 rows -> 512B of F32 row scales
		// before the 256B I8 owner.
		h1 := readOutShardHeader(t, outDir, multiShard1)
		checkOutHeader(t, h1, []outEntry{
			{rotA + ".scale", DTypeF32, [2]int64{0, 512}},
			{rotA, DTypeI8, [2]int64{512, 768}},
		})
		if !reflect.DeepEqual(h1.Tensors[0].Info.Shape, []int64{128}) {
			t.Errorf("rot.a.scale shape = %v, want [128] (one F32 per row)", h1.Tensors[0].Info.Shape)
		}
		if !reflect.DeepEqual(h1.Tensors[1].Info.Shape, []int64{128, 2}) {
			t.Errorf("rot.a shape = %v, want [128,2] (owner shape preserved)", h1.Tensors[1].Info.Shape)
		}

		// Shard 2: rot.b [2,128] -> 2 rows -> 8B of row scales before the
		// 256B I8 owner.
		h2 := readOutShardHeader(t, outDir, multiShard2)
		checkOutHeader(t, h2, []outEntry{
			{rotB + ".scale", DTypeF32, [2]int64{0, 8}},
			{rotB, DTypeI8, [2]int64{8, 264}},
		})
		if !reflect.DeepEqual(h2.Tensors[0].Info.Shape, []int64{2}) {
			t.Errorf("rot.b.scale shape = %v, want [2] (one F32 per row)", h2.Tensors[0].Info.Shape)
		}
		if !reflect.DeepEqual(h2.Tensors[1].Info.Shape, []int64{2, 128}) {
			t.Errorf("rot.b shape = %v, want [2,128] (owner shape preserved)", h2.Tensors[1].Info.Shape)
		}
	})

	t.Run("data bytes identical to merged output", func(t *testing.T) {
		checkShardsMatchMerged(t, outDir, mergedPath, inIdx)
	})

	t.Run("index: owners + scales in owner shards, file-order keys, total_size", func(t *testing.T) {
		outIdx, err := LoadIndex(filepath.Join(outDir, fixtureIndexName))
		if err != nil {
			t.Fatalf("LoadIndex (output): %v", err)
		}
		want := map[string]string{
			rotA + ".scale": multiShard1,
			rotA:            multiShard1,
			rotB + ".scale": multiShard2,
			rotB:            multiShard2,
		}
		if !reflect.DeepEqual(outIdx.WeightMap, want) {
			t.Errorf("output weight_map = %v, want %v", outIdx.WeightMap, want)
		}
		// Pinned: 512 (rot.a row scales) + 256 (rot.a) + 8 (rot.b row
		// scales) + 256 (rot.b) = sum of the per-shard data bytes.
		if got := outIdx.Metadata["total_size"]; got != float64(1032) {
			t.Errorf("total_size = %v, want 1032 (pinned)", got)
		}
		outRaw, err := os.ReadFile(filepath.Join(outDir, fixtureIndexName))
		if err != nil {
			t.Fatalf("reading output index: %v", err)
		}
		// Key order = file order: before-sibs precede their owners.
		got := weightMapKeyOrder(t, outRaw)
		wantOrder := []string{rotA + ".scale", rotA, rotB + ".scale", rotB}
		if !reflect.DeepEqual(got, wantOrder) {
			t.Errorf("output weight_map key order = %v, want %v (file order)", got, wantOrder)
		}
	})

	t.Run("output dir round-trips through DiscoverShards", func(t *testing.T) {
		shards, idx, err := DiscoverShards(outDir)
		if err != nil {
			t.Fatalf("DiscoverShards(outDir): %v", err)
		}
		if idx == nil {
			t.Fatal("expected the written index to drive discovery")
		}
		want := []string{filepath.Join(outDir, multiShard1), filepath.Join(outDir, multiShard2)}
		if !reflect.DeepEqual(shards, want) {
			t.Errorf("discovered shards = %v, want %v", shards, want)
		}
	})

	t.Run("target-none round-trip is byte-identical to the merged output", func(t *testing.T) {
		shards, idx, err := DiscoverShards(outDir)
		if err != nil {
			t.Fatalf("DiscoverShards(outDir): %v", err)
		}
		rtPath := filepath.Join(t.TempDir(), "roundtrip.safetensors")
		if _, err := ConvertModel(ConvertOptions{
			InputShards: shards,
			InputIndex:  idx,
			OutputPath:  rtPath,
			Default:     TargetNone,
		}); err != nil {
			t.Fatalf("ConvertModel (round-trip): %v", err)
		}
		rt, err := os.ReadFile(rtPath)
		if err != nil {
			t.Fatalf("reading round-trip output: %v", err)
		}
		merged, err := os.ReadFile(mergedPath)
		if err != nil {
			t.Fatalf("reading merged output: %v", err)
		}
		if !bytes.Equal(rt, merged) {
			t.Errorf("target-none round-trip of the output dir differs from the merged output (%d vs %d bytes)", len(rt), len(merged))
		}
	})
}

// TestConvertModelMultiFileNew4BitTargets is the multi-file-output shape
// of TestConvertModelMultiFileInt8 for mxfp4, nvfp4, and int4 on the
// multi fixture: pinned per-shard headers (vector-scale siblings before
// their owners, int4's scalar scale after), index entries for every
// sibling in the owner's shard with file-order keys, a summed total_size,
// and per-tensor byte identity with the merged output.
func TestConvertModelMultiFileNew4BitTargets(t *testing.T) {
	inIdx, err := LoadIndex(filepath.Join(fixtureDir, fixtureIndexName))
	if err != nil {
		t.Fatalf("LoadIndex: %v", err)
	}

	cases := []struct {
		name      string
		target    TargetKind
		shard1    []outEntry
		shard2    []outEntry
		weightMap map[string]string
		keyOrder  []string
		totalSize float64
	}{
		{
			name:   "mxfp4",
			target: TargetMxFP4,
			shard1: []outEntry{
				{nameUpProj + ".block_scale", DTypeU8, [2]int64{0, 1}},
				{nameUpProj, DTypeU8, [2]int64{1, 5}},
				{nameQProj + ".block_scale", DTypeU8, [2]int64{5, 6}},
				{nameQProj, DTypeU8, [2]int64{6, 8}},
			},
			shard2: []outEntry{
				{nameNorm + ".block_scale", DTypeU8, [2]int64{0, 1}},
				{nameNorm, DTypeU8, [2]int64{1, 3}},
				{namePosIDs, DTypeI32, [2]int64{3, 19}},
			},
			weightMap: map[string]string{
				nameUpProj + ".block_scale": multiShard1,
				nameUpProj:                  multiShard1,
				nameQProj + ".block_scale":  multiShard1,
				nameQProj:                   multiShard1,
				nameNorm + ".block_scale":   multiShard2,
				nameNorm:                    multiShard2,
				namePosIDs:                  multiShard2,
			},
			keyOrder: []string{
				nameUpProj + ".block_scale", nameUpProj,
				nameQProj + ".block_scale", nameQProj,
				nameNorm + ".block_scale", nameNorm,
				namePosIDs,
			},
			totalSize: 27, // (1+4)+(1+2) + (1+2)+16
		},
		{
			name:   "nvfp4",
			target: TargetNVFP4,
			shard1: []outEntry{
				{nameUpProj + ".global_scale", DTypeF32, [2]int64{0, 4}},
				{nameUpProj + ".block_scale", DTypeF8E4M3, [2]int64{4, 5}},
				{nameUpProj, DTypeU8, [2]int64{5, 9}},
				{nameQProj + ".global_scale", DTypeF32, [2]int64{9, 13}},
				{nameQProj + ".block_scale", DTypeF8E4M3, [2]int64{13, 14}},
				{nameQProj, DTypeU8, [2]int64{14, 16}},
			},
			shard2: []outEntry{
				{nameNorm + ".global_scale", DTypeF32, [2]int64{0, 4}},
				{nameNorm + ".block_scale", DTypeF8E4M3, [2]int64{4, 5}},
				{nameNorm, DTypeU8, [2]int64{5, 7}},
				{namePosIDs, DTypeI32, [2]int64{7, 23}},
			},
			weightMap: map[string]string{
				nameUpProj + ".global_scale": multiShard1,
				nameUpProj + ".block_scale":  multiShard1,
				nameUpProj:                   multiShard1,
				nameQProj + ".global_scale":  multiShard1,
				nameQProj + ".block_scale":   multiShard1,
				nameQProj:                    multiShard1,
				nameNorm + ".global_scale":   multiShard2,
				nameNorm + ".block_scale":    multiShard2,
				nameNorm:                     multiShard2,
				namePosIDs:                   multiShard2,
			},
			keyOrder: []string{
				nameUpProj + ".global_scale", nameUpProj + ".block_scale", nameUpProj,
				nameQProj + ".global_scale", nameQProj + ".block_scale", nameQProj,
				nameNorm + ".global_scale", nameNorm + ".block_scale", nameNorm,
				namePosIDs,
			},
			totalSize: 39, // (4+1+4)+(4+1+2) + (4+1+2)+16
		},
		{
			name:   "int4",
			target: TargetInt4,
			shard1: []outEntry{
				{nameUpProj, DTypeU8, [2]int64{0, 4}},
				{nameUpProj + ".scale", DTypeF32, [2]int64{4, 8}},
				{nameQProj, DTypeU8, [2]int64{8, 10}},
				{nameQProj + ".scale", DTypeF32, [2]int64{10, 14}},
			},
			shard2: []outEntry{
				{nameNorm, DTypeU8, [2]int64{0, 2}},
				{nameNorm + ".scale", DTypeF32, [2]int64{2, 6}},
				{namePosIDs, DTypeI32, [2]int64{6, 22}},
			},
			weightMap: map[string]string{
				nameUpProj:            multiShard1,
				nameUpProj + ".scale": multiShard1,
				nameQProj:             multiShard1,
				nameQProj + ".scale":  multiShard1,
				nameNorm:              multiShard2,
				nameNorm + ".scale":   multiShard2,
				namePosIDs:            multiShard2,
			},
			keyOrder: []string{
				nameUpProj, nameUpProj + ".scale",
				nameQProj, nameQProj + ".scale",
				nameNorm, nameNorm + ".scale",
				namePosIDs,
			},
			totalSize: 36, // (4+4)+(2+4) + (2+4)+16
		},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			outDir := t.TempDir()
			if _, err := ConvertModel(ConvertOptions{
				InputShards: multiShardPaths(),
				InputIndex:  inIdx,
				OutputDir:   outDir,
				Default:     tc.target,
			}); err != nil {
				t.Fatalf("ConvertModel: %v", err)
			}

			mergedPath := filepath.Join(t.TempDir(), "merged.safetensors")
			if _, err := ConvertModel(ConvertOptions{
				InputShards: multiShardPaths(),
				OutputPath:  mergedPath,
				Default:     tc.target,
			}); err != nil {
				t.Fatalf("ConvertModel (merged): %v", err)
			}

			t.Run("output dir has exactly the 2 shards + index", func(t *testing.T) {
				entries, err := os.ReadDir(outDir)
				if err != nil {
					t.Fatalf("reading output dir: %v", err)
				}
				got := make([]string, 0, len(entries))
				for _, e := range entries {
					got = append(got, e.Name())
				}
				want := []string{multiShard1, multiShard2, fixtureIndexName}
				if !reflect.DeepEqual(got, want) {
					t.Errorf("output dir = %v, want exactly %v", got, want)
				}
			})

			t.Run("per-shard headers", func(t *testing.T) {
				checkOutHeader(t, readOutShardHeader(t, outDir, multiShard1), tc.shard1)
				checkOutHeader(t, readOutShardHeader(t, outDir, multiShard2), tc.shard2)
			})

			t.Run("index: siblings in owner shards, key order, total_size", func(t *testing.T) {
				outIdx, err := LoadIndex(filepath.Join(outDir, fixtureIndexName))
				if err != nil {
					t.Fatalf("LoadIndex (output): %v", err)
				}
				if !reflect.DeepEqual(outIdx.WeightMap, tc.weightMap) {
					t.Errorf("output weight_map = %v, want %v", outIdx.WeightMap, tc.weightMap)
				}
				if got := outIdx.Metadata["total_size"]; got != tc.totalSize {
					t.Errorf("total_size = %v, want %v (sum of per-shard data bytes)", got, tc.totalSize)
				}
				outRaw, err := os.ReadFile(filepath.Join(outDir, fixtureIndexName))
				if err != nil {
					t.Fatalf("reading output index: %v", err)
				}
				got := weightMapKeyOrder(t, outRaw)
				if !reflect.DeepEqual(got, tc.keyOrder) {
					t.Errorf("output weight_map key order = %v, want %v (file order)", got, tc.keyOrder)
				}
			})

			t.Run("data bytes identical to merged output", func(t *testing.T) {
				checkShardsMatchMerged(t, outDir, mergedPath, inIdx)
			})

			t.Run("output dir is a loadable model directory", func(t *testing.T) {
				shards, idx, err := DiscoverShards(outDir)
				if err != nil {
					t.Fatalf("DiscoverShards(outDir): %v", err)
				}
				if idx == nil {
					t.Fatal("expected the written index to drive discovery")
				}
				want := []string{filepath.Join(outDir, multiShard1), filepath.Join(outDir, multiShard2)}
				if !reflect.DeepEqual(shards, want) {
					t.Errorf("discovered shards = %v, want %v", shards, want)
				}
			})
		})
	}
}

// TestConvertModelConfigMixedTargets runs one synthetic model through
// ConvertFile with a config that resolves six different tensors to six
// different targets (int8_convrot, mxfp4, nvfp4, int4, none, and the
// config default fp8_e4m3), and pins each tensor's output dtype, sibling
// layout, and report fields (scale, note, skip reason) to its resolved
// target.
func TestConvertModelConfigMixedTargets(t *testing.T) {
	convVals := make([]float32, 256) // a multiple of the ConvRot group size
	for i := range convVals {
		convVals[i] = float32(i%13-6) * 0.25
	}
	convVals[10] = 12.0
	mxVals := make([]float32, 64)
	for i := range mxVals {
		mxVals[i] = float32(i%5-2) * 0.5
	}
	nvVals := make([]float32, 48)
	for i := range nvVals {
		nvVals[i] = 0.5
	}
	nvVals[0] = 2688 // M = 6*448 -> global scale alpha = exactly 1
	i4Vals := make([]float32, 32)
	for i := range i4Vals {
		i4Vals[i] = 1.0
	}
	i4Vals[0] = 14.0 // maxAbs 14 -> int4 scale 14/7 = 2.0
	skipVals := make([]float32, 10)
	defVals := make([]float32, 32)
	for i := range defVals {
		defVals[i] = float32(i%7-3) * 0.1
	}
	in := writeF32Shard(t,
		f32Tensor{name: "w.convrot", vals: convVals},
		f32Tensor{name: "w.mx", vals: mxVals},
		f32Tensor{name: "w.nv", vals: nvVals},
		f32Tensor{name: "w.i4", vals: i4Vals},
		f32Tensor{name: "w.skip", vals: skipVals},
		f32Tensor{name: "w.def", vals: defVals},
	)

	cfgPath := filepath.Join(t.TempDir(), "config.json")
	cfg := `{
	  "default": "fp8_e4m3",
	  "rules": [
	    { "match": "w.convrot", "dtype": "int8_convrot" },
	    { "match": "w.mx", "dtype": "mxfp4" },
	    { "match": "w.nv", "dtype": "nvfp4" },
	    { "match": "w.i4", "dtype": "int4" },
	    { "pattern": "^w\\.skip$", "dtype": "none" }
	  ]
}`
	if err := os.WriteFile(cfgPath, []byte(cfg), 0o644); err != nil {
		t.Fatalf("writing config: %v", err)
	}
	cfgObj, err := LoadConfig(cfgPath)
	if err != nil {
		t.Fatalf("LoadConfig: %v", err)
	}

	outPath := filepath.Join(t.TempDir(), "out.safetensors")
	stats, err := ConvertFile(ConvertOptions{
		InputPath:  in,
		OutputPath: outPath,
		Config:     cfgObj,
	})
	if err != nil {
		t.Fatalf("ConvertFile: %v", err)
	}

	out, err := os.Open(outPath)
	if err != nil {
		t.Fatalf("opening output: %v", err)
	}
	defer out.Close()
	outHeader, _, err := ReadHeader(out)
	if err != nil {
		t.Fatalf("reading output header: %v", err)
	}

	// One sibling layout per resolved target, in input tensor order:
	// convrot's (1-D -> one row -> scalar) F32 scale before the I8 owner;
	// mxfp4's E8M0 block scales (64/32 = 2) before the packed owner;
	// nvfp4's F32 global scale + E4M3 block scales (48/16 = 3) before the
	// packed owner; int4's packed owner followed by its scalar F32 scale;
	// the "none" tensor passthrough at F32; the default fp8_e4m3 tensor.
	checkOutHeader(t, outHeader, []outEntry{
		{"w.convrot.scale", DTypeF32, [2]int64{0, 4}},
		{"w.convrot", DTypeI8, [2]int64{4, 260}},
		{"w.mx.block_scale", DTypeU8, [2]int64{260, 262}},
		{"w.mx", DTypeU8, [2]int64{262, 294}},
		{"w.nv.global_scale", DTypeF32, [2]int64{294, 298}},
		{"w.nv.block_scale", DTypeF8E4M3, [2]int64{298, 301}},
		{"w.nv", DTypeU8, [2]int64{301, 325}},
		{"w.i4", DTypeU8, [2]int64{325, 341}},
		{"w.i4.scale", DTypeF32, [2]int64{341, 345}},
		{"w.skip", DTypeF32, [2]int64{345, 385}},
		{"w.def", DTypeF8E4M3, [2]int64{385, 417}},
	})

	// Report fields per resolved target: only convrot and nvfp4 carry a
	// note; only int4 (like int8) carries a per-tensor scale; only the
	// "none" tensor is skipped.
	wantStats := []struct {
		name       string
		toDType    DType
		scale      float32
		note       string
		skippedWhy bool
	}{
		{"w.convrot", DTypeI8, 0, "convrot rows=1", false},
		{"w.mx", DTypeU8, 0, "", false},
		{"w.nv", DTypeU8, 0, "nvfp4 scale=1", false},
		{"w.i4", DTypeU8, 2.0, "", false},
		{"w.skip", DTypeF32, 0, "", true},
		{"w.def", DTypeF8E4M3, 0, "", false},
	}
	if len(stats) != len(wantStats) {
		t.Fatalf("got %d stats, want %d", len(stats), len(wantStats))
	}
	for i, w := range wantStats {
		s := stats[i]
		if s.Name != w.name {
			t.Errorf("stat[%d].Name = %q, want %q", i, s.Name, w.name)
			continue
		}
		if s.ToDType != w.toDType {
			t.Errorf("stat (%s).ToDType = %v, want %v", s.Name, s.ToDType, w.toDType)
		}
		if s.Scale != w.scale {
			t.Errorf("stat (%s).Scale = %v, want %v", s.Name, s.Scale, w.scale)
		}
		if s.Note != w.note {
			t.Errorf("stat (%s).Note = %q, want %q", s.Name, s.Note, w.note)
		}
		if (s.SkippedWhy != "") != w.skippedWhy {
			t.Errorf("stat (%s).SkippedWhy = %q, want non-empty = %v", s.Name, s.SkippedWhy, w.skippedWhy)
		}
	}
}

func TestConvertModelMultiFileErrors(t *testing.T) {
	t.Run("OutputPath and OutputDir both set", func(t *testing.T) {
		_, err := ConvertModel(ConvertOptions{
			InputShards: multiShardPaths(),
			OutputPath:  filepath.Join(t.TempDir(), "a.safetensors"),
			OutputDir:   t.TempDir(),
			Default:     TargetNone,
		})
		if err == nil || !strings.Contains(err.Error(), "mutually exclusive") {
			t.Fatalf("expected mutually-exclusive error, got %v", err)
		}
	})

	t.Run("multi-file output without input index", func(t *testing.T) {
		_, err := ConvertModel(ConvertOptions{
			InputShards: multiShardPaths(),
			OutputDir:   t.TempDir(),
			Default:     TargetNone,
		})
		if err == nil || !strings.Contains(err.Error(), "requires an input index") {
			t.Fatalf("expected missing-index error, got %v", err)
		}
	})
}

// TestConvertModelMultiFileRefusesOverwrite is the never-overwrite
// regression test for multi-file output: single-file output refuses an
// existing -out file (ResolveOutput), and multi-file output must get the
// same guarantee for every planned target - each output shard filename and
// the index. A refused run must fail up front, before any file is created:
// the pre-existing file is untouched and nothing else appears in the
// output directory.
func TestConvertModelMultiFileRefusesOverwrite(t *testing.T) {
	inIdx, err := LoadIndex(filepath.Join(fixtureDir, fixtureIndexName))
	if err != nil {
		t.Fatalf("LoadIndex: %v", err)
	}

	runRefused := func(t *testing.T, outDir, wantNamed string) {
		t.Helper()
		_, err := ConvertModel(ConvertOptions{
			InputShards: multiShardPaths(),
			InputIndex:  inIdx,
			OutputDir:   outDir,
			Default:     TargetFP8E4M3,
		})
		if err == nil {
			t.Fatal("ConvertModel: expected an overwrite-refusal error, got nil")
		}
		if !strings.Contains(err.Error(), "refusing to overwrite existing output file") {
			t.Fatalf("error = %q, want a refusing-to-overwrite error", err.Error())
		}
		if !strings.Contains(err.Error(), wantNamed) {
			t.Fatalf("error = %q, want it to name %s", err.Error(), wantNamed)
		}
	}

	dirHasOnly := func(t *testing.T, outDir string, want ...string) {
		t.Helper()
		entries, err := os.ReadDir(outDir)
		if err != nil {
			t.Fatalf("reading output dir: %v", err)
		}
		names := make([]string, 0, len(entries))
		for _, e := range entries {
			names = append(names, e.Name())
		}
		if !reflect.DeepEqual(names, want) {
			t.Errorf("output dir = %v, want only the pre-existing %v (nothing else created)", names, want)
		}
	}

	t.Run("pre-existing shard file is refused, content untouched", func(t *testing.T) {
		outDir := t.TempDir()
		pre := filepath.Join(outDir, multiShard1)
		content := []byte("pre-existing shard content")
		if err := os.WriteFile(pre, content, 0o644); err != nil {
			t.Fatalf("writing pre-existing shard: %v", err)
		}

		runRefused(t, outDir, multiShard1)

		got, err := os.ReadFile(pre)
		if err != nil {
			t.Fatalf("reading pre-existing shard: %v", err)
		}
		if !bytes.Equal(got, content) {
			t.Errorf("pre-existing shard content = %q, want it unchanged (%q)", got, content)
		}
		dirHasOnly(t, outDir, multiShard1)
	})

	t.Run("pre-existing index is refused, content untouched", func(t *testing.T) {
		outDir := t.TempDir()
		pre := filepath.Join(outDir, fixtureIndexName)
		content := []byte(`{"weight_map":{}}`)
		if err := os.WriteFile(pre, content, 0o644); err != nil {
			t.Fatalf("writing pre-existing index: %v", err)
		}

		runRefused(t, outDir, fixtureIndexName)

		got, err := os.ReadFile(pre)
		if err != nil {
			t.Fatalf("reading pre-existing index: %v", err)
		}
		if !bytes.Equal(got, content) {
			t.Errorf("pre-existing index content = %q, want it unchanged (%q)", got, content)
		}
		dirHasOnly(t, outDir, fixtureIndexName)
	})

	t.Run("error names the first existing target", func(t *testing.T) {
		outDir := t.TempDir()
		for _, name := range []string{multiShard1, fixtureIndexName} {
			if err := os.WriteFile(filepath.Join(outDir, name), []byte("old"), 0o644); err != nil {
				t.Fatalf("writing pre-existing %s: %v", name, err)
			}
		}

		runRefused(t, outDir, multiShard1) // shards are checked before the index
		dirHasOnly(t, outDir, multiShard1, fixtureIndexName)
	})
}

// writeShardAt writes a single-file safetensors input with the given
// header and data bytes at an explicit path, for building model-directory
// inputs in tests.
func writeShardAt(t *testing.T, path string, h *Header, data []byte) {
	t.Helper()
	f, err := CreateOutputFile(path, h)
	if err != nil {
		t.Fatalf("CreateOutputFile(%s): %v", path, err)
	}
	if _, err := f.Write(data); err != nil {
		f.Close()
		t.Fatalf("writing data to %s: %v", path, err)
	}
	if err := f.Close(); err != nil {
		t.Fatalf("closing %s: %v", path, err)
	}
}

// TestConvertFailedRunRemovesPartialOutputs is the cleanup-on-error
// regression test: a file whose header declares a 256-element tensor
// (512 data bytes) but whose data block is truncated to 100 bytes is
// valid and self-consistent at planning, so the run fails mid-stream on a
// ReadAt past EOF - not at planning. A failed run must leave no partial
// outputs behind: no output file in single-file mode, and no shard files
// and no index in multi-file mode, while a successful run must still
// leave its outputs in place. Input files are never touched.
func TestConvertFailedRunRemovesPartialOutputs(t *testing.T) {
	// 256-element BF16 tensor = 512 declared data bytes, but only 100
	// bytes are actually in the file: valid header, short file, failure
	// in the streaming pass.
	truncInfo := TensorInfo{DType: DTypeBF16, Shape: []int64{256}, DataOffsets: [2]int64{0, 512}}
	truncData := make([]byte, 100)

	t.Run("single-file mode removes the partial output", func(t *testing.T) {
		in := writeRawSafetensors(t, "trunc.w", truncInfo, truncData)
		out := filepath.Join(t.TempDir(), "out.safetensors")
		_, err := ConvertFile(ConvertOptions{
			InputPath:  in,
			OutputPath: out,
			Default:    TargetFP8E4M3,
		})
		if err == nil {
			t.Fatal("ConvertFile: expected a mid-stream error, got nil")
		}
		// The error comes from the streaming pass (naming the tensor),
		// not from planning.
		if !strings.Contains(err.Error(), `converting tensor "trunc.w"`) {
			t.Errorf("error = %q, want a mid-stream error naming trunc.w", err.Error())
		}
		if _, statErr := os.Stat(out); !os.IsNotExist(statErr) {
			t.Errorf("output %s exists after the failed run, want no file (stat err = %v)", out, statErr)
		}
	})

	t.Run("multi-file mode removes all shards and the index", func(t *testing.T) {
		// A two-shard model directory: shard 1 is valid (its output shard
		// is fully written before the failure), shard 2 is truncated (the
		// run dies while streaming it), so at the failure both output
		// shards exist on disk.
		dir := t.TempDir()
		shard1 := filepath.Join(dir, multiShard1)
		shard2 := filepath.Join(dir, multiShard2)
		writeShardAt(t, shard1, &Header{Tensors: []TensorEntry{{
			Name: "ok.w",
			Info: TensorInfo{DType: DTypeBF16, Shape: []int64{8}, DataOffsets: [2]int64{0, 16}},
		}}}, make([]byte, 16))
		writeShardAt(t, shard2, &Header{Tensors: []TensorEntry{{
			Name: "trunc.w",
			Info: truncInfo,
		}}}, truncData)
		idxJSON := `{"weight_map":{"ok.w":"` + multiShard1 + `","trunc.w":"` + multiShard2 + `"}}`
		if err := os.WriteFile(filepath.Join(dir, fixtureIndexName), []byte(idxJSON), 0o644); err != nil {
			t.Fatalf("writing index: %v", err)
		}
		inIdx, err := LoadIndex(filepath.Join(dir, fixtureIndexName))
		if err != nil {
			t.Fatalf("LoadIndex: %v", err)
		}

		inputSize := map[string]int64{}
		for _, p := range []string{shard1, shard2} {
			fi, err := os.Stat(p)
			if err != nil {
				t.Fatalf("stat %s: %v", p, err)
			}
			inputSize[p] = fi.Size()
		}

		outDir := t.TempDir()
		_, err = ConvertModel(ConvertOptions{
			InputShards: []string{shard1, shard2},
			InputIndex:  inIdx,
			OutputDir:   outDir,
			Default:     TargetFP8E4M3,
		})
		if err == nil {
			t.Fatal("ConvertModel: expected a mid-stream error, got nil")
		}
		if !strings.Contains(err.Error(), `converting tensor "trunc.w"`) {
			t.Errorf("error = %q, want a mid-stream error naming trunc.w", err.Error())
		}
		// No shard files and no index: the output dir is empty.
		entries, err := os.ReadDir(outDir)
		if err != nil {
			t.Fatalf("reading output dir: %v", err)
		}
		if len(entries) != 0 {
			names := make([]string, 0, len(entries))
			for _, e := range entries {
				names = append(names, e.Name())
			}
			t.Errorf("output dir = %v, want empty (no shards, no index)", names)
		}
		// Input files are never touched.
		for p, want := range inputSize {
			fi, err := os.Stat(p)
			if err != nil {
				t.Errorf("input %s missing after the failed run: %v", p, err)
				continue
			}
			if fi.Size() != want {
				t.Errorf("input %s size = %d, want %d (inputs are never touched)", p, fi.Size(), want)
			}
		}
	})

	t.Run("successful runs still leave their outputs", func(t *testing.T) {
		okInfo := TensorInfo{DType: DTypeBF16, Shape: []int64{8}, DataOffsets: [2]int64{0, 16}}

		// Single file.
		in := writeRawSafetensors(t, "ok.w", okInfo, make([]byte, 16))
		out := filepath.Join(t.TempDir(), "out.safetensors")
		if _, err := ConvertFile(ConvertOptions{
			InputPath:  in,
			OutputPath: out,
			Default:    TargetFP8E4M3,
		}); err != nil {
			t.Fatalf("ConvertFile: %v", err)
		}
		if _, err := os.Stat(out); err != nil {
			t.Errorf("single-file output missing after a successful run: %v", err)
		}

		// Multi-file: the committed multi fixture converts, and the output
		// dir holds exactly its 2 shards + the index.
		inIdx, err := LoadIndex(filepath.Join(fixtureDir, fixtureIndexName))
		if err != nil {
			t.Fatalf("LoadIndex: %v", err)
		}
		outDir := t.TempDir()
		if _, err := ConvertModel(ConvertOptions{
			InputShards: multiShardPaths(),
			InputIndex:  inIdx,
			OutputDir:   outDir,
			Default:     TargetFP8E4M3,
		}); err != nil {
			t.Fatalf("ConvertModel: %v", err)
		}
		entries, err := os.ReadDir(outDir)
		if err != nil {
			t.Fatalf("reading output dir: %v", err)
		}
		if len(entries) != 3 {
			names := make([]string, 0, len(entries))
			for _, e := range entries {
				names = append(names, e.Name())
			}
			t.Errorf("output dir = %v, want the 2 shards + index", names)
		}
	})
}

// TestToF32SliceInto pins the decode-into-scratch variant the streaming
// passes use: it decodes into the caller's slice (returning the filled
// prefix over the same backing array), agrees with the allocating
// toFloat32Slice wrapper on every supported source dtype, and rejects an
// undersized dst instead of panicking.
func TestToF32SliceInto(t *testing.T) {
	vals := []float32{0, 1, -1.5, 3.25, -1e-38}
	raw := map[DType][]byte{}
	raw[DTypeF32] = func() []byte {
		b := make([]byte, 4*len(vals))
		for i, v := range vals {
			binary.LittleEndian.PutUint32(b[i*4:], math.Float32bits(v))
		}
		return b
	}()
	raw[DTypeF64] = func() []byte {
		b := make([]byte, 8*len(vals))
		for i, v := range vals {
			binary.LittleEndian.PutUint64(b[i*8:], math.Float64bits(float64(v)))
		}
		return b
	}()
	encode16 := func(enc func(float32) uint16) []byte {
		b := make([]byte, 2*len(vals))
		for i, v := range vals {
			binary.LittleEndian.PutUint16(b[i*2:], enc(v))
		}
		return b
	}
	raw[DTypeF16] = encode16(f32ToF16)
	raw[DTypeBF16] = encode16(f32ToBF16)

	for dtype, r := range raw {
		// Deliberately oversized dst: the result must be the filled
		// prefix of exactly this backing array.
		dst := make([]float32, len(vals)+3)
		got, err := toFloat32SliceInto(dst, r, dtype)
		if err != nil {
			t.Fatalf("%s: %v", dtype, err)
		}
		if len(got) != len(vals) || cap(got) != len(vals)+3 {
			t.Fatalf("%s: len/cap = %d/%d, want %d/%d", dtype, len(got), cap(got), len(vals), len(vals)+3)
		}
		if &got[0] != &dst[0] {
			t.Fatalf("%s: result does not alias the caller's dst", dtype)
		}
		want, err := toFloat32Slice(r, dtype)
		if err != nil {
			t.Fatalf("%s: wrapper: %v", dtype, err)
		}
		if !slices.Equal(got, want) {
			t.Fatalf("%s: into = %v, wrapper = %v", dtype, got, want)
		}
	}

	// F32 is lossless: pin the exact values.
	got, err := toFloat32SliceInto(make([]float32, len(vals)), raw[DTypeF32], DTypeF32)
	if err != nil {
		t.Fatalf("f32: %v", err)
	}
	if !slices.Equal(got, vals) {
		t.Fatalf("f32: got %v, want %v", got, vals)
	}

	// Error cases: undersized dst, non-multiple raw length, unsupported dtype.
	if _, err := toFloat32SliceInto(make([]float32, 1), raw[DTypeF32], DTypeF32); err == nil {
		t.Fatal("undersized dst: expected an error")
	}
	if _, err := toFloat32SliceInto(make([]float32, 4), raw[DTypeF32][:10], DTypeF32); err == nil {
		t.Fatal("non-multiple raw length: expected an error")
	}
	if _, err := toFloat32SliceInto(make([]float32, 4), []byte{0, 0, 0, 0}, DTypeI8); err == nil {
		t.Fatal("unsupported dtype: expected an error")
	}
}
